// One source-derived 32-group forward core, reused for rows then columns.
module dct_compensated(
 input wire clk,rst_n,frame_start,in_valid,
 input wire [511:0] samples,
 output wire in_ready, output reg out_valid,
 output reg [2047:0] coefficients
);
reg busy;reg [3:0] phase;
reg signed [31:0] data[0:63];reg signed [31:0] rows[0:63];
wire accept=in_valid && in_ready;
assign in_ready=!busy && !frame_start && rst_n;
wire flip_enable=1'b0;
wire signed [31:0] p0=phase<8 ? data[phase*8+0] : rows[0*8+(phase-8)];
wire signed [31:0] y0;
wire signed [31:0] p1=phase<8 ? data[phase*8+1] : rows[1*8+(phase-8)];
wire signed [31:0] y1;
wire signed [31:0] p2=phase<8 ? data[phase*8+2] : rows[2*8+(phase-8)];
