wire signed [31:0] y5;
wire signed [31:0] p6=phase<8 ? data[phase*8+6] : rows[6*8+(phase-8)];
wire signed [31:0] y6;
wire signed [31:0] p7=phase<8 ? data[phase*8+7] : rows[7*8+(phase-8)];
wire signed [31:0] y7;
dct_compensated_core arithmetic(.flip_enable(flip_enable),.p0(p0),.y0(y0),.p1(p1),.y1(y1),.p2(p2),.y2(y2),.p3(p3),.y3(y3),.p4(p4),.y4(y4),.p5(p5),.y5(y5),.p6(p6),.y6(y6),.p7(p7),.y7(y7));
integer i;
always @(posedge clk or negedge rst_n) begin
 if(!rst_n) begin busy<=0;phase<=0;out_valid<=0;coefficients<=0;
  for(i=0;i<64;i=i+1) begin data[i]<=0;rows[i]<=0;end
 end else if(frame_start) begin busy<=0;phase<=0;out_valid<=0;coefficients<=0;
 end else begin
  out_valid<=0;
  if(accept) begin
   busy<=1;phase<=0;
   for(i=0;i<64;i=i+1) data[i]<=$signed({24'd0,samples[i*8+:8]})-32'sd128;
  end else if(busy) begin
   if(phase<8) rows[phase*8+0]<=y0; else coefficients[(0*8+phase-8)*32+:32]<=y0;
