   if(phase<8) rows[phase*8+2]<=y2; else coefficients[(2*8+phase-8)*32+:32]<=y2;
   if(phase<8) rows[phase*8+3]<=y3; else coefficients[(3*8+phase-8)*32+:32]<=y3;
   if(phase<8) rows[phase*8+4]<=y4; else coefficients[(4*8+phase-8)*32+:32]<=y4;
   if(phase<8) rows[phase*8+5]<=y5; else coefficients[(5*8+phase-8)*32+:32]<=y5;
   if(phase<8) rows[phase*8+6]<=y6; else coefficients[(6*8+phase-8)*32+:32]<=y6;
   if(phase<8) rows[phase*8+7]<=y7; else coefficients[(7*8+phase-8)*32+:32]<=y7;
   if(phase==15) begin busy<=0;out_valid<=1;end
   else phase<=phase+1'b1;
  end
 end
